import { useEffect, useState } from "react";

// ─── Mock data (replace with real API calls) ───────────────────────────────
const MOCK_STATS = {
  totalUsers: 1284,
  quizzesTaken: 9741,
  avgScore: 72,
  totalQuestions: 3200,
};

const MOCK_CATEGORIES = [
  { id: 1, name: "General Knowledge", questions: 50, attempts: 2400, color: "#7C3AED" },
  { id: 2, name: "Science",           questions: 40, attempts: 1870, color: "#059669" },
  { id: 3, name: "History",           questions: 35, attempts: 1200, color: "#D97706" },
  { id: 4, name: "Technology",        questions: 45, attempts:  980, color: "#2563EB" },
  { id: 5, name: "Geography",         questions: 30, attempts:  760, color: "#DB2777" },
  { id: 6, name: "Sports",            questions: 28, attempts:  530, color: "#DC2626" },
];

const MOCK_LEADERBOARD = [
  { rank: 1,  username: "alex_r",   initials: "AR", bestScore: 98, quizzes: 42, accuracy: 95 },
  { rank: 2,  username: "sara_k",   initials: "SK", bestScore: 96, quizzes: 38, accuracy: 91 },
  { rank: 3,  username: "mike_j",   initials: "MJ", bestScore: 94, quizzes: 55, accuracy: 88 },
  { rank: 4,  username: "priya_l",  initials: "PL", bestScore: 91, quizzes: 29, accuracy: 85 },
  { rank: 5,  username: "tom_n",    initials: "TN", bestScore: 89, quizzes: 61, accuracy: 82 },
  { rank: 6,  username: "zara_h",   initials: "ZH", bestScore: 87, quizzes: 33, accuracy: 79 },
  { rank: 7,  username: "raj_b",    initials: "RB", bestScore: 85, quizzes: 27, accuracy: 76 },
  { rank: 8,  username: "emma_w",   initials: "EW", bestScore: 83, quizzes: 44, accuracy: 73 },
  { rank: 9,  username: "liu_x",    initials: "LX", bestScore: 81, quizzes: 19, accuracy: 70 },
  { rank: 10, username: "nina_p",   initials: "NP", bestScore: 79, quizzes: 36, accuracy: 68 },
];

const AVATAR_COLORS = [
  { bg: "#EDE9FE", text: "#5B21B6" },
  { bg: "#D1FAE5", text: "#065F46" },
  { bg: "#FEF3C7", text: "#92400E" },
  { bg: "#DBEAFE", text: "#1E40AF" },
  { bg: "#FCE7F3", text: "#9D174D" },
  { bg: "#FEE2E2", text: "#991B1B" },
  { bg: "#F0FDF4", text: "#166534" },
  { bg: "#FFF7ED", text: "#9A3412" },
  { bg: "#EFF6FF", text: "#1D4ED8" },
  { bg: "#FDF2F8", text: "#86198F" },
];

// ─── Helpers ───────────────────────────────────────────────────────────────
function useCountUp(target, duration = 1200) {
  const [value, setValue] = useState(0);
  useEffect(() => {
    let start = null;
    const step = (ts) => {
      if (!start) start = ts;
      const progress = Math.min((ts - start) / duration, 1);
      setValue(Math.floor(progress * target));
      if (progress < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }, [target, duration]);
  return value;
}

function AnimatedBar({ pct, color, delay = 0 }) {
  const [width, setWidth] = useState(0);
  useEffect(() => {
    const t = setTimeout(() => setWidth(pct), delay);
    return () => clearTimeout(t);
  }, [pct, delay]);
  return (
    <div style={{ height: 5, background: "#F3F4F6", borderRadius: 99, overflow: "hidden", marginTop: 10 }}>
      <div style={{
        height: "100%", borderRadius: 99, background: color,
        width: `${width}%`, transition: "width 0.9s cubic-bezier(0.4,0,0.2,1)",
      }} />
    </div>
  );
}

// ─── Sub-components ────────────────────────────────────────────────────────
function StatCard({ label, value, suffix = "", sub, delay }) {
  const [visible, setVisible] = useState(false);
  useEffect(() => { const t = setTimeout(() => setVisible(true), delay); return () => clearTimeout(t); }, [delay]);
  const count = useCountUp(visible ? value : 0, 1000);

  return (
    <div style={{
      background: "#fff", border: "1px solid #F0F0F0", borderRadius: 14,
      padding: "18px 20px", opacity: visible ? 1 : 0,
      transform: visible ? "translateY(0)" : "translateY(12px)",
      transition: "opacity 0.5s ease, transform 0.5s ease",
      boxShadow: "0 1px 4px rgba(0,0,0,0.05)",
    }}>
      <p style={{ fontSize: 12, color: "#9CA3AF", fontWeight: 500, marginBottom: 8, letterSpacing: "0.05em", textTransform: "uppercase" }}>{label}</p>
      <p style={{ fontSize: 30, fontWeight: 700, color: "#111827", lineHeight: 1, fontFamily: "'Georgia', serif" }}>
        {count.toLocaleString()}{suffix}
      </p>
      {sub && <p style={{ fontSize: 12, color: "#9CA3AF", marginTop: 6 }}>{sub}</p>}
    </div>
  );
}

function CategoryCard({ cat, maxAttempts, delay }) {
  const [visible, setVisible] = useState(false);
  useEffect(() => { const t = setTimeout(() => setVisible(true), delay); return () => clearTimeout(t); }, [delay]);
  const pct = Math.round((cat.attempts / maxAttempts) * 100);

  return (
    <div style={{
      background: "#fff", border: "1px solid #F0F0F0", borderRadius: 14,
      padding: "16px 18px", opacity: visible ? 1 : 0,
      transform: visible ? "translateY(0)" : "translateY(10px)",
      transition: "opacity 0.5s ease, transform 0.5s ease",
      boxShadow: "0 1px 4px rgba(0,0,0,0.04)",
    }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
        <p style={{ fontWeight: 600, fontSize: 14, color: "#111827" }}>{cat.name}</p>
        <span style={{
          fontSize: 11, fontWeight: 600, padding: "3px 8px", borderRadius: 99,
          background: cat.color + "18", color: cat.color,
        }}>{cat.questions}Q</span>
      </div>
      <p style={{ fontSize: 12, color: "#9CA3AF", marginTop: 4 }}>{cat.attempts.toLocaleString()} attempts</p>
      <AnimatedBar pct={pct} color={cat.color} delay={delay + 300} />
      <p style={{ fontSize: 11, color: "#C4C4C4", marginTop: 4, textAlign: "right" }}>{pct}% of top category</p>
    </div>
  );
}

function RankBadge({ rank }) {
  const medals = { 1: { bg: "#FEF3C7", text: "#92400E", symbol: "1" }, 2: { bg: "#F1F5F9", text: "#475569", symbol: "2" }, 3: { bg: "#FEF0E7", text: "#9A3412", symbol: "3" } };
  const m = medals[rank];
  if (m) return (
    <div style={{ width: 26, height: 26, borderRadius: "50%", background: m.bg, color: m.text, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700 }}>{m.symbol}</div>
  );
  return <span style={{ fontSize: 13, color: "#9CA3AF", fontWeight: 500, width: 26, textAlign: "center", display: "block" }}>{rank}</span>;
}

function LeaderboardRow({ entry, delay }) {
  const [visible, setVisible] = useState(false);
  useEffect(() => { const t = setTimeout(() => setVisible(true), delay); return () => clearTimeout(t); }, [delay]);
  const ac = AVATAR_COLORS[(entry.rank - 1) % AVATAR_COLORS.length];

  return (
    <div style={{
      display: "grid", gridTemplateColumns: "36px 1fr 90px 70px 110px",
      alignItems: "center", gap: 10, padding: "11px 18px",
      borderBottom: "1px solid #F9FAFB",
      opacity: visible ? 1 : 0, transform: visible ? "translateX(0)" : "translateX(-8px)",
      transition: "opacity 0.4s ease, transform 0.4s ease",
    }}>
      <div style={{ display: "flex", justifyContent: "center" }}><RankBadge rank={entry.rank} /></div>

      <div style={{ display: "flex", alignItems: "center", gap: 10, minWidth: 0 }}>
        <div style={{ width: 32, height: 32, borderRadius: "50%", background: ac.bg, color: ac.text, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 700, flexShrink: 0 }}>
          {entry.initials}
        </div>
        <span style={{ fontWeight: 600, fontSize: 14, color: "#111827", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{entry.username}</span>
      </div>

      <div style={{ textAlign: "center" }}>
        <span style={{ fontSize: 13, fontWeight: 700, color: "#7C3AED" }}>{entry.bestScore}%</span>
      </div>

      <div style={{ textAlign: "center", fontSize: 13, color: "#6B7280" }}>{entry.quizzes}</div>

      <div>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
          <span style={{ fontSize: 11, color: "#9CA3AF" }}>accuracy</span>
          <span style={{ fontSize: 11, fontWeight: 600, color: "#374151" }}>{entry.accuracy}%</span>
        </div>
        <div style={{ height: 4, background: "#F3F4F6", borderRadius: 99 }}>
          <div style={{ height: "100%", borderRadius: 99, background: entry.accuracy > 85 ? "#059669" : entry.accuracy > 70 ? "#D97706" : "#DC2626", width: `${entry.accuracy}%`, transition: "width 1s ease" }} />
        </div>
      </div>
    </div>
  );
}

// ─── Main Dashboard ────────────────────────────────────────────────────────
export default function Dashboard() {
  // TODO: Replace with real API calls
  // const [stats, setStats] = useState(null);
  // useEffect(() => { fetch('/api/stats').then(r => r.json()).then(setStats); }, []);

  const stats = MOCK_STATS;
  const categories = MOCK_CATEGORIES;
  const leaderboard = MOCK_LEADERBOARD;
  const maxAttempts = Math.max(...categories.map((c) => c.attempts));

  return (
    <div style={{ maxWidth: 900, margin: "0 auto", padding: "32px 20px", fontFamily: "'system-ui', sans-serif", background: "#FAFAFA", minHeight: "100vh" }}>

      {/* Header */}
      <div style={{ marginBottom: 28 }}>
        <h1 style={{ fontSize: 26, fontWeight: 700, color: "#111827", fontFamily: "'Georgia', serif" }}>Dashboard</h1>
        <p style={{ fontSize: 13, color: "#9CA3AF", marginTop: 4 }}>
          {new Date().toLocaleDateString("en-US", { weekday: "long", year: "numeric", month: "long", day: "numeric" })}
        </p>
      </div>

      {/* Stat Cards */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 14, marginBottom: 32 }}>
        <StatCard label="Total Users"     value={stats.totalUsers}     sub="+48 this week"          delay={0}   />
        <StatCard label="Quizzes Taken"   value={stats.quizzesTaken}   sub="all time"               delay={80}  />
        <StatCard label="Avg. Score"      value={stats.avgScore}       suffix="%" sub="across all quizzes" delay={160} />
        <StatCard label="Total Questions" value={stats.totalQuestions} sub="in 6 categories"        delay={240} />
      </div>

      {/* Categories */}
      <h2 style={{ fontSize: 13, fontWeight: 600, color: "#9CA3AF", letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 14 }}>Categories</h2>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 12, marginBottom: 32 }}>
        {categories.map((cat, i) => (
          <CategoryCard key={cat.id} cat={cat} maxAttempts={maxAttempts} delay={i * 60} />
        ))}
      </div>

      {/* Leaderboard */}
      <h2 style={{ fontSize: 13, fontWeight: 600, color: "#9CA3AF", letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 14 }}>Leaderboard</h2>
      <div style={{ background: "#fff", border: "1px solid #F0F0F0", borderRadius: 14, overflow: "hidden", boxShadow: "0 1px 4px rgba(0,0,0,0.05)" }}>
        {/* Table header */}
        <div style={{ display: "grid", gridTemplateColumns: "36px 1fr 90px 70px 110px", gap: 10, padding: "10px 18px", borderBottom: "1px solid #F3F4F6", background: "#FAFAFA" }}>
          {["#", "User", "Best Score", "Quizzes", "Accuracy"].map((h) => (
            <p key={h} style={{ fontSize: 11, fontWeight: 600, color: "#9CA3AF", letterSpacing: "0.05em", textTransform: "uppercase", textAlign: h === "Best Score" || h === "Quizzes" ? "center" : "left" }}>{h}</p>
          ))}
        </div>

        {leaderboard.map((entry, i) => (
          <LeaderboardRow key={entry.rank} entry={entry} delay={i * 50} />
        ))}
      </div>
    </div>
  );
}
